class StreamService {
    fun bad(list: List<String>) {
        list.parallelStream().forEach { println(it) }
    }
}

class ParallelService {
    fun bad(list: List<String>) {
        list.stream().parallel().forEach { println(it) }
    }
}

class SequentialService {
    fun good(list: List<String>) {
        list.stream().sequential().forEach { println(it) }
    }
}

class SequenceService {
    fun good(list: List<String>) {
        list.asSequence().forEach { println(it) }
    }
}
